<?php
require_once dirname(__DIR__) . '/includes/auth.php'; require_role('ADMIN'); $pdo=db();
$rows=$pdo->query('SELECT i.*, s.student_name, j.position_title, c.company_name, cr.representative_name FROM interview i JOIN application a ON a.application_id=i.application_id JOIN student s ON s.student_id=a.student_id JOIN job_vacancy j ON j.job_id=a.job_id JOIN company c ON c.company_id=j.company_id JOIN company_representative cr ON cr.representative_id=i.representative_id ORDER BY i.interview_date,i.interview_time')->fetchAll();
$pageTitle='Interviews'; include dirname(__DIR__).'/includes/header.php'; ?>
<div class="table-wrap"><table><thead><tr><th>Student / Job</th><th>Company</th><th>Representative</th><th>Schedule</th><th>Stage</th><th>Status</th><th>Result</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['student_name']) ?></strong><br><?= e($r['position_title']) ?></td><td><?= e($r['company_name']) ?></td><td><?= e($r['representative_name']) ?></td><td><?= e($r['interview_date']) ?> <?= e(substr($r['interview_time'],0,5)) ?><br><span class="muted"><?= e($r['location_or_link']) ?></span></td><td><?= e($r['interview_stage']) ?></td><td><span class="badge <?= badge_class($r['interview_status']) ?>"><?= e($r['interview_status']) ?></span></td><td><?= e($r['interview_result']) ?></td></tr><?php endforeach;?></tbody></table></div>
<?php include dirname(__DIR__).'/includes/footer.php'; ?>
